//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::hash::slice_hash`; the
//! native twin is `benches/native/Bench/SliceHash.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::hash;
use lean_runtime_bench::{mixed, run, step, SEED};
use std::hint::black_box;
#[allow(unused_variables)]
fn kernel(inp: &(String, usize), n: u64) -> u64 {
    let (s, a) = (&inp.0, &inp.1);
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = acc.wrapping_add(hash::slice_hash(black_box(&s.as_bytes()[*a..])));
    }
    acc as u64
}

fn main() {
    run(
        || {
            let s = mixed();
            let a = s.char_indices().nth(3).unwrap().0;
            (s, a)
        },
        kernel,
    )
}
